SELECT id, service, level, latency_ms, payload_json, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['version'] AS version FROM app_logs WHERE service IN ('billing', 'auth', 'search')
